<script setup lang="ts">
import { useForm } from '@inertiajs/vue3'; import BaseCard from './BaseCard.vue'; import FormButton from './FormButton.vue';
const props = defineProps<{ user: { id: string; name: string; email: string; active: boolean; role: string }; roles: string[] }>();
const form = useForm({ active: props.user.active, role: props.user.role }); const password = useForm({ password: '' });
</script>
<template><BaseCard><h2 class="text-heading font-bold">{{ user.name }}</h2><p class="mb-5 break-all">{{ user.email }} · {{ user.active ? '✓ Actif' : '⛔ Désactivé' }}</p><form class="space-y-5" @submit.prevent="form.put(`/administration/comptes/${user.id}`)"><label>Rôle<select v-model="form.role" class="field"><option v-for="role in roles" :key="role">{{ role }}</option></select></label><label class="flex min-h-14 items-center gap-3"><input v-model="form.active" type="checkbox" class="h-6 w-6">Compte actif</label><p>Décocher bloque l'accès et ferme les sessions du compte.</p><p v-for="e in form.errors" :key="e" role="alert">{{ e }}</p><FormButton :busy="form.processing">Enregistrer le compte</FormButton></form><details class="mt-6"><summary class="min-h-14 cursor-pointer py-3">Réinitialiser le mot de passe</summary><form class="space-y-4" @submit.prevent="password.put(`/administration/comptes/${user.id}/mot-de-passe`, { onSuccess: () => password.reset() })"><label>Nouveau mot de passe<input v-model="password.password" type="password" class="field" autocomplete="new-password" minlength="12" required></label><p v-for="e in password.errors" :key="e" role="alert">{{ e }}</p><FormButton :busy="password.processing">Réinitialiser</FormButton></form></details></BaseCard></template>
